using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    internal static string DescribeContinuationContractStateForCostTesting(
        CombatPredictionSimulator simulator, CombatRootSnapshot root, Player player)
        => DescribeContinuationContractState(simulator, root, player);

    private async Task AssertSmartPotionCostBoundAsync(CombatState live, Player player)
    {
        await ClearPlayerPilesAsync(player);
        await InjectCardAsync(live, player, new() { CardId = "OFFERING", Pile = "Hand", Count = 2 });
        await InjectCardAsync(live, player, new() { CardId = "STRIKE_IRONCLAD", Pile = "Hand" });
        foreach (PotionModel? potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player, "SHACKLING_POTION");
        InjectPotionForTest(player, "BOTTLED_POTENTIAL");
        SetEnergy(player, 3);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        if (!root.UsesComponentHealingCertificate || root.InitialRemainingHealingUpperBound != 0)
            throw new InvalidOperationException("Smart-cost fixture has no closed root: " + root.ComponentHealingRejection);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var parent = root.ForkSimulator();
        string parentBefore = DescribeContinuationContractState(parent, root, player);
        SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null) with
        {
            FixedBudget = true, VerifyIncrementalSearch = true, MaxDegreeOfParallelism = 16,
            DetailedDiagnostics = false, MeasurePhasePerformance = false, BudgetOverrideMilliseconds = null,
            PotionPolicy = SolverPotionPolicy.Smart, PotionStrategy = new(SolverPotionPolicy.Smart, []),
            RelicTargets = [], StopAtAcceptableBattleHpLoss = false,
        };
        SolverDisplayNames names = SolverDisplayNames.Capture(live);
        BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
        var proof = await Task.Run(() => CombatBeamSolver.SmartPotionCostProbeForTesting(root, names, damage, policy));
        if (ContinuationStamp.CaptureLive(live).StateText != liveBefore
            || DescribeContinuationContractState(parent, root, player) != parentBefore)
            throw new InvalidOperationException("Cost-bound probe changed root parent/live/history/RNG.");
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        PotionModel nativePotion = player.GetPotionAtSlotIndex(1)!;
        GameAction nativeUse = await SolverController.EnqueueAndCaptureActionAsync(
            action => action is UsePotionAction use && use.PotionIndex == 1 && ReferenceEquals(use.Player, player),
            () => nativePotion.EnqueueManualUse(player.Creature), deadline.Token);
        await nativeUse.CompletionTask.WaitAsync(deadline.Token);
        string expected = ContinuationStamp.CapturePredicted(player, proof.ExpensivePartial.Snapshot.Simulator,
            proof.ExpensivePartial.Turn, root.Forecast, root.StartTurnNumber).StateText;
        if (ContinuationStamp.CaptureLive(live).StateText != expected
            || DescribeContinuationContractState(parent, root, player) != parentBefore)
            throw new InvalidOperationException("Native high-cost potion full state/parent isolation differs.");
        _completedChecks.Add("SmartPotionCostBound:ActualCompleteOfferingWinner:Costs9/14:CheapPossibleKept:"
            + "ExpensiveImpossiblePruned:UnknownFeedExhaustKept:WholeReplayMatches:16ForkHistoryRngParentIsolation:"
            + "NativeBottledPotentialFullState:RewardCreditOnce:BossPolicies:InvalidBaselineKept");
    }
}

internal sealed partial class CombatBeamSolver
{
    internal sealed record SmartPotionCostProof(SearchNode ExpensivePartial);

    internal static SmartPotionCostProof SmartPotionCostProbeForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy)
    {
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        var withoutPotion = new CombatBeamSolver(root, names, damage, policy, deadline.Token,
            searchProfile: policy.Profile, potionPolicyOverride: SolverPotionPolicy.Disabled);
        SearchNode witness = CreateOpeningSearchSeed(withoutPotion.Replay([]));
        for (int i = 0; i < 2; i++)
            witness = withoutPotion.CostChildForTesting(witness, withoutPotion.PrepareCardActions(witness)
                .First(action => action.Action.CardId == "OFFERING").Action);
        witness = withoutPotion.CostChildForTesting(witness, withoutPotion.PrepareCardActions(witness)
            .First(action => action.Action.CardId == "STRIKE_IRONCLAD").Action);
        if (!witness.IsTerminal || witness.Snapshot.HasRisk || !witness.Snapshot.AllEnemiesDead
            || witness.Snapshot.PlayerDead || witness.Snapshot.ProjectedDeathSaveUseCount != 0
            || ExplicitPotionUseCount(witness) != 0)
            throw new InvalidOperationException("Cost proof needs an actual complete compliant potion-free victory.");
        int deficit = ActEndingBossPolicy.StrategicHpDeficit(witness.Snapshot.CumulativePlayerHpLost, 0,
            witness.Snapshot.RecoveredPlayerHp + ActEndingBossPolicy.RankedPostCombatRelicHeal(root.PostCombatRelicHeal,
                true, witness.Snapshot.PlayerHp, witness.Snapshot.PlayerMaxHp), BossHpRelief.None,
            witness.Snapshot.DeathSaveHpRestored) - witness.Snapshot.StrategicHpCredit;
        PotionFreePolicyBaseline baseline = new(true, deficit, witness.Snapshot.PlayerHp, witness.Snapshot.CombatEndedTurn);
        var member = new CombatBeamSolver(root, names, damage, policy, deadline.Token,
            searchProfile: policy.Profile, potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
            potionFreePolicyBaseline: baseline, maximumPotionUses: 1, minimumPotionUses: 1,
            directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
        if (!member.ComponentSmartBoundEnabledForTesting)
            throw new InvalidOperationException("Cost proof did not enter the original closed Smart gate.");
        SearchNode start = CreateOpeningSearchSeed(member.Replay([]));
        SearchNode UseSlot(int slot) => member.CostChildForTesting(start,
            member.PreparePotionActions(start).Single(action => action.Action.PotionSlot == slot).Action);
        SearchNode cheap = UseSlot(0), expensive = UseSlot(1);
        if (cheap.Snapshot.ExplicitPotionStrategicCost != 9 || expensive.Snapshot.ExplicitPotionStrategicCost != 14)
            throw new InvalidOperationException("Actual native potion values do not prove the expected cost gap.");
        int oldCeiling = member._smartPotionEligibilityHpCeiling!.Value;
        int lower = StrategicHpLowerBound(expensive.Snapshot, BossHpRelief.None,
            member.RemainingHealingPotential(expensive.Snapshot));
        if (lower > oldCeiling || member.ApplySmartPotionEligibilityBound([cheap]).Count != 1
            || member.ApplySmartPotionEligibilityBound([expensive]).Count != 0
            || member.ComponentSmartCostBoundPrunedForTesting != 1)
            throw new InvalidOperationException($"New cost proof lacks an additional safe prune: lower={lower} old={oldCeiling}.");
        string expensiveBefore = UnattendedTestRunner.DescribeContinuationContractStateForCostTesting(
            (CombatPredictionSimulator)expensive.Snapshot.Simulator, root, root.PlayerIdentity);
        var full = member.Replay(expensive.Actions);
        if (UnattendedTestRunner.DescribeContinuationContractStateForCostTesting(
                (CombatPredictionSimulator)full.Simulator, root, root.PlayerIdentity) != expensiveBefore)
            throw new InvalidOperationException("Cost prefix differs from full replay.");
        using (SimulationNotificationIsolation.Enter())
        {
            var unknown = ((CombatPredictionSimulator)expensive.Snapshot.Simulator).Fork();
            unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Feed>(), root.PlayerIdentity),
                PileType.Exhaust, root.PlayerIdentity, resultKind: CardGenerationResultKind.Fixed);
            SimulationSnapshot unknownSnapshot = member.Snapshot(unknown, expensive.Turn, expensive.ActionCount,
                expensive.Snapshot.ShufflesCrossed, SearchBoundaryReason.None, new ForkableSet<uint>());
            SearchNode unknownNode = expensive with { Snapshot = unknownSnapshot, StateKey = unknownSnapshot.StateKey,
                Score = unknownSnapshot.Score, CombatProgress = CombatProgressState.Capture(unknownSnapshot) };
            if (member.RemainingHealingPotential(unknownSnapshot) != int.MaxValue
                || member.ApplySmartPotionEligibilityBound([unknownNode]).Count != 1)
                throw new InvalidOperationException("Already-spent cost discarded an unknown recovery branch.");
        }
        var forks = Enumerable.Range(0, 16).Select(_ => Task.Run(() =>
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            var child = ((CombatPredictionSimulator)expensive.Snapshot.Simulator).Fork();
            return UnattendedTestRunner.DescribeContinuationContractStateForCostTesting(child, root, root.PlayerIdentity);
        })).ToArray();
        Task.WaitAll(forks);
        if (forks.Any(fork => fork.Result != expensiveBefore)
            || UnattendedTestRunner.DescribeContinuationContractStateForCostTesting(
                (CombatPredictionSimulator)expensive.Snapshot.Simulator, root, root.PlayerIdentity) != expensiveBefore)
            throw new InvalidOperationException("Cost proof changed immutable metadata across owned Forks.");
        foreach (BossHpRelief relief in Enum.GetValues<BossHpRelief>())
        foreach (int credit in new[] { 0, 9, 99 })
        {
            int? ceiling = SmartPotionEligibilityHpCeiling(baseline, 1, 9, credit, relief, 14);
            int expected = baseline.HpDeficit - PotionUsePolicy.SmartRequiredHpSaved(
                PotionUsePolicy.ApplyReplacementCredit(14, 1, credit), relief);
            if (ceiling != expected) throw new InvalidOperationException("Cost bound changed reward/boss policy.");
        }
        if (SmartPotionEligibilityHpCeiling(null, 1, 9, 0, BossHpRelief.None, 14) is not null
            || SmartPotionEligibilityHpCeiling(baseline with { Won = false }, 1, 9, 0, BossHpRelief.None, 14) is not null
            || SmartPotionEligibilityHpCeiling(baseline with { DeathSaveUseCount = 1 }, 1, 9, 0, BossHpRelief.None, 14) is not null
            || SmartPotionEligibilityHpCeiling(baseline, 1, 9, 0, BossHpRelief.None, -1) is not null)
            throw new InvalidOperationException("Cost proof accepted invalid witness or cost metadata.");
        return new(expensive);
    }
}
